<?php $fs=static fn(string $s):string=>ucfirst(str_replace('_',' ',$s)); ?>
<header class="panel-page-heading"><div><span>Reserva #<?= (int)$reserva['id'] ?></span><h1><?= e($reserva['chacara_nome']) ?></h1><p><?= e($reserva['cliente_nome']) ?> · <?= e($reserva['proprietario_nome']) ?></p></div><a class="btn btn-outline" href="<?= url('/admin/reservas') ?>">Voltar</a></header>
<section class="panel-card"><dl class="client-summary-list"><div><dt>Status</dt><dd><?= e($fs($reserva['status_reserva'])) ?></dd></div><div><dt>Pagamento</dt><dd><?= e($fs($reserva['status_pagamento'])) ?></dd></div><div><dt>Periodo</dt><dd><?= e(date('d/m/Y',strtotime($reserva['data_inicio']))) ?> a <?= e(date('d/m/Y',strtotime($reserva['data_fim']))) ?></dd></div><?php if(!empty($reserva['divergencia_pagamento'])):?><div><dt>Atencao</dt><dd>Pagamento com divergencia; requer conciliacao.</dd></div><?php endif;?></dl>
<form method="post" action="<?= url('/admin/reservas/'.(int)$reserva['id'].'/transicao') ?>"><?= csrf_field() ?><label>Motivo obrigatorio<textarea name="motivo" maxlength="500" required></textarea></label><div class="client-detail-actions"><?php foreach(['cancelar'=>'Cancelar','aprovar_cancelamento'=>'Aprovar cancelamento','recusar_cancelamento'=>'Recusar cancelamento','iniciar'=>'Iniciar','finalizar'=>'Finalizar'] as $a=>$l):?><button class="btn btn-outline" name="acao" value="<?= $a ?>" type="submit"><?= $l ?></button><?php endforeach;?></div></form></section>
<section class="panel-card"><div class="panel-card-heading"><h2>Historico</h2></div><?php foreach($historico as $h):?><p><strong><?= e($fs($h['status_novo'])) ?></strong> · <?= e(date('d/m/Y H:i',strtotime($h['criado_em']))) ?><?= $h['motivo']?' · '.e($h['motivo']):'' ?></p><?php endforeach;?></section>
